import{_ as u,a0 as a,w as i,s,ao as l,I as r,x as t,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"戴文的Linux內核專題：09 配置內核(5) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：09 配置內核(5) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：09 配置內核(5) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：09 配置內核(5) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/09 The Linux Kernel--Configuring the Kernel Part 5","title":"戴文的Linux內核專題：09 配置內核(5)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/09 The Linux Kernel--Configuring the Kernel Part 5.md","filePath":"[post].md"}'),c={name:"The Linux Kernel/09 The Linux Kernel--Configuring the Kernel Part 5.md"};function d(C,e,x,m,P,T){const p=a("Link");return i(),s("div",null,[e[11]||(e[11]=l(`<h1 id="戴文的linux內核專題-09-配置內核-5" tabindex="-1">戴文的Linux內核專題：09 配置內核(5) <a class="header-anchor" href="#戴文的linux內核專題-09-配置內核-5" aria-label="Permalink to “戴文的Linux內核專題：09 配置內核(5)”">​</a></h1><p>Linux內核擁有許多可以配置的特性，接下來我們還有許多要配置。</p><p>下一個可以配置的特性是x86的隨機數生成器(x86 architectural random number generator (ARCH_RANDOM))。記住，我們現在配置的是針對AMD64系統的內核代碼。這個隨機數生成器使用Intel x86的RDRAND指令。這並不通用，所以為了一個更輕量的內核我禁用了它。</p><p>接着，我們可以啓用或者禁用&quot;Supervisor Mode Access Prevention (X86_SMAP)&quot;。這是Intel處理器使用的安全特性。SMAP在一些條件下只允許內核訪問用户空間。這個有助於保護用户空間。如果啓用，這裏有一點性能和內核大小的開銷，但是開銷很小。由於我是用的是AMD系統，所以我禁用了這個特性。</p><p>開發者可以啓用&quot;EFI runtime service support (EFI)&quot;。只有在有EFI固件的系統上啓用它。擁有這個特性，內核可以使用的EFI服務。EFI是一個操作系統和硬件如何交流的規範，所以EFI固件是使用這個規範的硬件代碼。因為我沒有EFI固件，所以我禁用了它。</p><p>這是一個應該被啓用的有用的安全方式(Enable seccomp to safely compute untrusted bytecode (SECCOMP))。這個安全特性在使用非可信的字節碼的數值計算(執行大量計算的軟件)中使用。字節碼(可移植代碼)是一種被解釋器有效讀取的代碼。字節碼不是源代碼，但它也不是彙編或者二進制代碼。非可信的代碼是一種可能導致系統/數據損壞的代碼。可能會破壞系統或者毀壞數據的非可信的代碼通過seccomp被隔離在獨立的地址空間中。這是通過文件描述符傳輸的方法。通常上，最好啓用這個安全特性，即使會有一些性能開銷，除非你在製作一個需要榨乾性能的內核。</p><p>這裏是另外一個安全特性(Enable -fstack-protector buffer overflow detection (CC_STACKPROTECTOR))。緩衝溢出是數據被寫在超出了它的內存界限而進入了鄰近的內存中。這是一個安全威脅。一些惡意軟件使用緩衝區溢出來破壞系統。啓用這個會使用GCC選項 &quot;-fstack-protector&quot;。GCC是一個Linux編譯器，在你配置完成後用它來編譯內核。這個編譯器參數會在返回地址前在棧上加入一個canary值(特殊的安全代碼)。這個值會在返回前被驗證。當內存溢出發生時，canary值會得到覆蓋消息。這時，會導致內核崩潰。如許多人知道的那樣，內核錯誤意味着系統將要崩潰，但是這比系統被入侵或者數據永久損害的好。發生內核錯誤，系統會重啓，但是如果緩衝溢出則可能導致系統被入侵。一個簡單的重啓無法修復破壞（譯註：但也不會更壞）。你必須用GCC 4.2或者更高版本支持這個參數的GCC來編譯內核。</p><p>提示：要知道你使用的版本號，在命令列內鍵入&quot;gcc --version&quot;。</p><p>在這之後，我們可以配置定時器頻率。配置工具建議使用250Hz，所以我們使用這個值。</p><p>Timer frequency</p><p>1. 100 HZ (HZ_100)</p><p>&gt;2. 250 HZ (HZ_250)</p><p>3. 300 HZ (HZ_300)</p><p>4. 1000 HZ (HZ_1000)</p><p>choice[1-4?]: 2</p><p>使用1000Hz通常來講對許多系統而言太快了。定時器頻率決定着定時器中斷被使用的頻率。這有助於在時間線上的系統操作。程序並不是隨機地執行一條命令，相反它們會等到定時器中斷結束。這保持着有組織和結構的處理。頻率為100Hz的定時器中斷之間的時間是10ms，250Hz是4ms，1000Hz是1ms。現在許多開發者會馬上想到1000Hz是最好的。好吧，這取決於你對開銷的要求。一個更大的定時器頻率意味着更多的能源消耗和更多的能源被利用(在定時器上)，產生更多的熱量。更多的熱量意味着硬件損耗的更快。</p><p>注意：如果某個特定的特性對你並不重要或者你不確定該選擇什麼，就使用配置工具選擇的默認值。比如，就我現在正在配置的內核而言，使用哪個定時器對我並不重要。總的來説，如果你沒有特別的原因去選擇任何一個選項時，就使用默認值。</p><p>下面這個有趣的系統調用可能會對一些用户有用(kexec system call (KEXEC))。kexec調用會關閉當前內核去啓動另外一個或者重啓當前內核。硬件並不會關閉，並且這個調用可以無需固件的幫助工作。bootloader是不執行的(bootloader是啓動操作系統的軟件) 。這個重啓發生在操作系統級別上而不是硬件上。使用這個系統調用會快於執行一個標準的關機或者重啓，這會保持硬件在加電狀態。這個系統調用並不能工作在所有系統上。為了更高性能，啓用這個熱啓動功能。</p><p>為了使用kexec，對重啓後要使用的內核使用如下命令替換 <code>&lt;kernel-image&gt;</code>。同樣，使用之前我們講過的內核參數替換<code>&lt;command-line-options&gt;</code> (我會在以後的文章中更深入的討論。)</p><pre><code>kexec -l &lt;kernel-image&gt; --append=&quot;&lt;command-line-options&gt;”
</code></pre><p>特別地，我這裏輸入：</p><pre><code>kexec -l /boot/vmlinuz-3.8.0-27-generic –append=&quot;root=/dev/sda1&quot;
</code></pre><p>注意：硬件有時不需要重置，所以這不依賴於kexec。</p><p>下面，我們有一個適用於kexec的調試特性(kernel crash dumps (CRASH_DUMP))。當kexec被調用時，一個崩潰信息(crash dump)會生成。除非你有必要調試kexec，否則這個並不必要。我禁用了這個特性。</p><p>再者，我們有另外一個kexec特性(kexec jump (KEXEC_JUMP))。kexec跳允許用户在原始內核和kexec啓動的內核之間切換。</p><p>最好對內核啓動地址使用默認值(Physical address where the kernel is loaded (PHYSICAL_START) [0x1000000])。</p><p>下一個內核選項(Build a relocatable kernel (RELOCATABLE))允許內核放在內存的任何地方。內核文件會增大10%，但是超出部分會在執行時從內存移除。許多人也許想知道這為什麼很重要。在2.6.20內核前，救援內核(rescue kernel)必須被配置和編譯運行在不同的內存地址上。當這個特性發明後，開發者不必再編譯兩個內核。救援內核不會在第一個已加載的內核的地方加載，因為該塊內存已被佔用或者發生了錯誤。(如果你正在使用救援內核，那麼明顯第一個內核發生了錯誤)</p><p>下面這個特性應該在可以增加CPU數量的系統中啓用，除非你有特別的理由不去這麼做(Support for hot-pluggable CPUs (HOTPLUG_CPU))。配置工具會自動啓用這個特性。在這個特性下，你可以在一個擁有很多處理器的系統上激活/停用一個CPU，這並不是説在系統中插入新的CPU，所有的CPU必須已經安裝在系統中。</p><p>下面的選項會讓我們選擇設置上面的特性是否默認啓用(Set default setting of cpu0_hotpluggable (BOOTPARAM_HOTPLUG_CPU0))。為了性能最好禁用這個特性直到需要的時候。</p><p>接着的這個調試特性允許開發者調試CPU熱插拔特性(Debug CPU0 hotplug (DEBUG_HOTPLUG_CPU0))。我禁用了它。</p><p>為了兼容舊版本的glibc(<code>&lt;2.3.3</code>)，可以啓用這個特性(Compat VDSO support (COMPAT_VDSO))。這適用於通過映射32位在VDSO(虛擬動態鏈接共享對象)的舊式地址。Glibc是GNC C庫；這是GNU工程實現的C標準庫。</p><p>如果系統內核被用於一個缺乏完整功能的bootloader上，那麼啓用這個特性(Built-in kernel command line (CMDLINE_BOOL))。這允許用户在內核自身上使用一條命令列（譯註：及其參數），那麼管理員可以修復內核問題。如果bootloader已經有了一條命令列(像grub)，那麼這個特性不必啓用。</p><p>現在我們可以配置ACPI和電源了。首先,我們被要求選擇系統是否可以掛起到內存(Suspend to RAM and standby (SUSPEND))。高級配置和電源接口(ACPI)是一種對於設備配置和電源管理的開放標準。掛起系統會將數據放在內存上，同時硬件進入一種低功耗的狀態。系統不會完全關機。如果用户需要計算機進入一個低功耗的狀態，但是希望保留當前已打開程序時是非常有用的。關閉一個系統會完全關閉系統電源並且清理內存。</p><p>下面，我們可以啓用睡眠(Hibernation (aka &#39;suspend to disk&#39;) (HIBERNATION))。睡眠就像掛起模式，但是內存中所有數據被保存到硬盤上，並且設備完全關閉。這允許用户在電源恢復後繼續使用他們已打開的程序。</p><p>這裏,我們可以設置默認的恢復分區(Default resume partition (PM_STD_PARTITION))。很少有開發者和管理員需要這個特性。當系統從睡眠中恢復時，他會加載默認的恢復分區。</p><p>在這之後,我們可以啓用&quot;Opportunistic sleep (PM_AUTOSLEEP)&quot;。這會讓內核在沒有活躍的喚醒調用被調用時進入掛起或者睡眠狀態。這意味着空閒的系統將會進入掛起模式以節省電源。我啓用了這個特性。</p><p>接下來，是詢問關於&quot;User space wakeup sources interface (PM_WAKELOCKS)&quot;。啓用這個特性將會允許喚醒源對象被激活、停用，並通過基於sysfs接口由用户空間創建。喚醒源對象會追蹤喚醒事件源。</p><p>sysfs是位於/sys/的虛擬文件系統。這個虛擬文件系統包含了關於設備的信息。當進入/sys/時，它似乎是硬盤的一部分，但是這個並不是一個真正的掛載點。這些文件實際存在於內存中。這與/proc/是同一個概念。</p><p>注意:&quot;/sysfs/&quot;是一個文件夾，而&quot;/sysfs&quot;則可以是一個根目錄下名為&quot;sysfs&quot;的文件。許多Linux用户會混淆這兩種命名約定。</p><p>如果啓用了上面的選項,那麼你可以設置&quot;Maximum number of user space wakeup sources (0 = no limit) (PM_WAKELOCKS_LIMIT)&quot;。最好選擇默認，那麼你就可以啓用垃圾收集器(Garbage collector for user space wakeup sources (PM_WAKELOCKS_GC))。垃圾收集是一種內存管理方式。</p><p>注意: 在需要更多內存的系統中，通常最好在大多數情況下儘可能啓用垃圾收集。不然內存會消耗得更快且雜亂。</p><p>下一個電源選項關於IO設備(Run-time PM core functionality (PM_RUNTIME))。這個選項允許IO硬件在運行時進入低功耗狀態。硬件必須支持這個才行，不是所有硬件都支持。</p><p>與其他許多內核組件一樣，如果啓用了(Power Management Debug Support)，電源管理代碼同樣有調試支持。我禁用了這個選項。</p><p>注意: 注意這些我引用/顯示的配置工具上的選項或問題不再顯示選項代碼(括號間所有的大寫字母)。這是因為我沒有使用基於ncurses的配置工具(make menuconfig)而是使用默認工具去得到選項、設置和問題。記住，&quot;make config&quot;缺乏保存當前進度的能力。</p><p>在這之後,配置工具會啓用&quot;ACPI (Advanced Configuration and Power Interface) Support&quot;。最好允許這個電源管理規範。通常配置工具會啓用這個特性。</p><p>為了允許向後兼容，啓用&quot;Deprecated /proc/acpi files&quot;。新的實現使用更新的在/sys下的實現。我禁用了這個選項。一個相似的問題詢問關於&quot;Deprecated power /proc/acpi directories&quot;。通常上,如果你禁用了這些文件，你不再需要這些文件夾，所以我禁用了他們。一些舊的程序可能會使用這些文件和文件夾。如果你在給舊的的Linux系統上編譯一個新的內核，最好啓用這個選項。</p><p>下面，我們有另外一個文件接口可以啓用或者禁用(EC read/write access through)。這會在/sys/kernek/debug/ec下創建一個嵌入式控制器接口。嵌入式控制器通常在筆記本中讀取傳感器，內核代碼通過系統的BIOS表提供的ACPI代碼訪問嵌入式控制器。</p><p>這裏有另外一個可以啓用或者禁用的向後兼容特性 (Deprecated /proc/acpi/event support)。acpi守護進程可能會讀取/proc/api/event來管理ACPI生成的驅動。不同於這個接口，守護進程使用netlink事件或者輸入層來得到送給用户空間的事件，acpi守護進程管理ACPI事件。</p><p>下一個選項允許開發者啓用一個特性，它會通知內核現在使用的是交流電源(AC Adapter)還是電池。下一個選項從/proc/acpi/battery/ (Battery)中提供電池信息。</p><p>為了內核在電源/睡眠按鈕按下或者蓋子合上時不同表現，啓用這個“按鈕”選項(Button)。這些事件在/proc/acpi/event/中控制。比如這樣的行為，如果在用户賬户的電源選項啓用了掛起，當筆記本電腦的蓋子關閉後系統將會掛起。</p><p>下一個ACPI擴展是針對顯卡的(Video)。</p><p>ACPI風扇控制可以被啓用/禁用(Fan)。最好啓用ACPI風扇管理，這有助於節能。</p><p>我們正在進一步配置內核中，但在接下來的文章中還有更多要做。</p><hr>`,54)),r("p",null,[e[1]||(e[1]=t("via: ",-1)),o(p,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-5.4424/"},{default:n(()=>[...e[0]||(e[0]=[t("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-5.4424/",-1)])]),_:1})]),r("p",null,[e[4]||(e[4]=t("譯者：",-1)),o(p,{href:"https://github.com/geekpi"},{default:n(()=>[...e[2]||(e[2]=[t("geekpi",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),o(p,{href:"https://github.com/wxy"},{default:n(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),r("p",null,[e[8]||(e[8]=t("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),o(p,{href:"http://linux.cn/"},{default:n(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const k=u(c,[["render",d]]);export{L as __pageData,k as default};
